def find_min_max_path_sum(N, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    def bfs(start):
        visited = [False] * (N + 1)
        queue = deque([(start, 0)])
        max_sum = start
        max_length = 0

        while queue:
            node, length = queue.popleft()
            visited[node] = True
            if length > max_length:
                max_length = length
                max_sum = node
            elif length == max_length and node > max_sum:
                max_sum = node

            for neighbor in graph[node]:
                if not visited[neighbor]:
                    queue.append((neighbor, length + 1))

        return max_sum, max_length

    S = [0] * (N + 1)
    for i in range(1, N + 1):
        if not graph[i]:
            S[i] = i
        else:
            max_sum, _ = bfs(i)
            S[i] = max_sum

    A = min(S)
    B = max(S)

    # Find x and y such that A * x = B * y
    for x in range(1, 1001):
        for y in range(1, 1001):
            if A * x == B * y:
                return x, y

    return -1, -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        N = int(data[index])
        M = int(data[index + 1])
        edges = []
        index += 2
        for i in range(M):
            X = int(data[index])
            Y = int(data[index + 1])
            edges.append((X, Y))
            index += 2
        x, y = find_min_max_path_sum(N, edges)
        results.append(f"{x} {y}")

    print("\n".join(results))

if __name__ == "__main__":
    main()
